    exact imp_trans''! this $ by
      apply imply_conj'!;
      intro ψ hq;
      simp at hq;
      rcases hq with (rfl | ⟨ψ, hq, rfl⟩)
      . apply and₁!;
      . suffices 𝓢 ⊢! ⋀□'^[n]Γ ➝ □^[n]ψ by exact dhyp_and_left! this;
        apply generate_conj'!;
        simpa;

